    ('planet-transit', 'Ṣalawāt', 'درود شریف'),
    ('planet-transit', 'Blessings upon the Prophet ﷺ', 'نبی کریم ﷺ پر درود'),
    ('planet-transit', 'Always beneficial, opens spiritual doors', 'روایتی تعبیر میں ہمیشہ مفید اور روحانی دروازے کھولنے والا سمجھا جاتا ہے'),
    ('planet-transit', 'Lubān wa Mayʿah Sāʾilah', 'لوبان و میعہ سائلہ'),
    ('planet-transit', 'Transit Practice -', 'عبور کا معمول -'),
